SELECT t.s_store_id, t.s_store_name, t.i_item_id, t.i_product_name, t.t_shift, t.total_net_loss, t.item_rank FROM ( SELECT s.s_store_id, s.s_store_name, i.i_item_id, i.i_product_name, td.t_shift, SUM(sr.sr_net_loss) AS total_net_loss, RANK() OVER (PARTITION BY s.s_store_id, td.t_shift ORDER BY SUM(sr.sr_net_loss) DESC) AS item_rank FROM store_returns sr JOIN store s ON sr.sr_store_sk = s.s_store_sk JOIN item i ON sr.sr_item_sk = i.i_item_sk JOIN time_dim td ON sr.sr_return_time_sk = td.t_time_sk GROUP BY s.s_store_id, s.s_store_name, i.i_item_id, i.i_product_name, td.t_shift ) t WHERE t.item_rank <= 5 ORDER BY t.s_store_id, t.t_shift, t.item_rank
